  AwakerTalent_122607_TalentDesc_1 = {
    Text = "Après avoir joué 2 cartes « Frappe », « Mouchette » effectue un suivi, infligeant des dégâts aléatoires équivalents à 30 % de l'Attaque de Mouchette, ce qui est considéré comme une « Frappe ». Cela peut se produire un maximum de 4 fois par tour."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "Rencontre dramatique"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Ce talent n'est effectif que dans les étapes « Règne Astral ».\nLa Constitution, l'Attaque et la Défense de cet Éveilleur +[Arg1]%, et il obtient [Arg2] Fragments de clé lors de son premier Éveil.\nL'effet de déclenchement de Poison de tous les Éveilleurs +[Arg3]%. \nChaque cumul d'« Ivresse » réduit en outre les dégâts infligés par les ennemis « Humanoïdes » de 1%, et lorsque l'« Ivresse » est retirée, chaque cumul inflige des Dégâts Fixes égaux à 1% des PV Max de la cible aux ennemis « Humanoïdes »."
  },
