  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Lorsque Arachne est dans l'équipe, le Royaume ultradimensionnel se retisse en Singularité: Ultra.\nNavette dimensionnelle : Après avoir joué la première Carte d'instruction à chaque tour, une Copie de Base Vide de celle-ci sera placée dans l'Espace Hyperspatial et recevra 25 charges de phare de singularité. Cela ne peut pas se déclencher pendant les Tours Ultra. Si une carte déclenche la Navette dimensionnelle, elle bénéficie également des effets du phare de singularité.\nPhare de singularité : Pour chaque charge, les Dégâts Finaux d'une carte, le gain fixe de Force & Dégâts des tentacules, le Poison Fixe & la Contre-attaque Fixe augmentent chacun de +2% ; le Bouclier Final, la Régénération de PV et la Force réduite augmentent chacun de +1%. Cet effet se dissipe lorsque la carte est jouée. Les cartes avec cet effet ne peuvent pas déclencher la Navette dimensionnelle.\nEspace Hyperspatial : Lorsqu'il est plein, commencer le Tour Ultra ne met pas fin au tour et n'en commence pas un nouveau ; défaussez toutes les cartes non-Garder, résolvez leurs effets Vide, récupérez toutes les cartes de l'Espace Hyperspatial et définissez l'Arithmetica à 5. Le tour actuel continue en tant que Tour Ultra.\nAnnihilation de Singularité : Récupérez la carte la plus à gauche de l'Espace Hyperspatial et placez-la en main. Temps de recharge de 3 tours.\nAu début de l'investigation, gagnez +50% d'Amplification de Dégâts et 15 charges de Prisme de Singularité.\nPrisme de Singularité : Les effets de toutes les Cartes d'instruction augmentent comme si elles avaient ce nombre de charges de phare de singularité.\nHyperdimension Maîtrise : Pour chaque point de Maîtrise de Royaume, les charges de phare de singularité provenant du Prisme de Singularité et de la Navette dimensionnelle augmentent de 0,05%.\nUltra pur : Si l'équipe est composée uniquement d'Éveilleurs Ultra ou du Chaos, l'effet d'Hyperdimension Maîtrise et l'Amplification de Dégâts du Royaume sont doublés."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Fil du destin"
  },
  AwakerTalent_130395_TalentDesc_1 = {
