  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Ce talent n'est effectif que dans les étapes du « Chapitre des Étoiles ».\nLa Constitution, l'Attaque et la Défense de ce Corps éveillé +[Arg1]%, et il obtient [Arg2] Fragment de clé lors de son premier Éveil.\nLe Corps éveillé sélectionné par « Le Chant de Saya » gagne [Arg3] charges de « Fiesta de propagation », et le prochain Décret Clé s'active 2 fois.\nSaya inflige +[Arg4]% de Corrosion aux ennemis « Chair »."
  },
