    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre Stellaire».\n·La Constitution, l'Attaque et la Défense de cet Éveilleur augmentent de [Arg1] %, et cet Éveilleur obtient [Arg2] points de Fragment de clé après avoir joué Éveiller pour la première fois.\n·«Ombre Sauvage Infinie» inflige l'Effet de Force réduite, le multiplicateur de Force obtenu augmente de [Arg3]%, et chaque activation permet à «Lance Souillée par le Crime» de bénéficier d'un bonus de Force supplémentaire de [Arg4]%, plafonné à 1200%."
  },
