  AwakerTalent_131854_TalentDesc_1 = {
    Text = "Lorsque Saya est dans l'équipe, le Royaume de la Chair mute en Propagation : Caro.\n\nFusion d'Embryon : La Fusion d'Embryon gagnée par tour augmente à 50~100, en fonction des PV perdus. Le plafond de Fusion d'Embryon passe de 100 à 200. Lorsque le plafond est atteint, ajoutez 1 « Embryon de Propagule » en main.\n\nEmbryon de Propagule : Jouer cette carte n'accorde plus de Taux Critique. Dévorer n'accorde plus de Bouclier ni de Force Temporaire. La première fois que chaque Corps éveillé consomme un « Embryon de Propagule » par tour, il gagne 40 charges de « Fiesta de propagation » : Chaque charge améliore les effets Finaux suivants de la prochaine Exaltation de ce Corps éveillé ce tour de 1% : Dégâts Finaux, Bouclier Fixe, Régénération de PV Fixe, Force Fixe/Force réduite, Bonus de dégâts des tentacules, Poison Fixe et Contre-attaque Fixe.\n\nForge Écarlate : L'accumulation automatique À chaque début de tour passe à 10% des PV perdus, jusqu'à 50% des PV Max. Ne s'accumule plus à la fin du combat. Temps de recharge de 3 tours.\n\nÉrosion écarlate : Après avoir utilisé la Forge Écarlate, infligez de la Corrosion à tous les ennemis égale à 1% de leurs PV Max. Plus la Forge Écarlate consommée est importante, plus l'effet de Corrosion est puissant, jusqu'à +100%. Inflige un effet de Corrosion 5× contre les ennemis « Coquille vide ».\n\nAu début de l'exploration, PV Max +10%, Amplification de Dégâts de l'équipe +50%, et tous les Corps éveillés gagnent 20 charges de « Fiesta de propagation » À chaque début de tour. Si l'équipe est composée uniquement de Corps éveillés de la Chair ou du Chaos, l'Amplification de Dégâts accordée par cet effet est doublée.\nLa Maîtrise de Royaume devient « Maîtrise Propagation : Caro » : Chaque point de Maîtrise de Royaume augmente les charges de « Fiesta de propagation » gagnées grâce à « Propagation : Caro » de 0,05%.\n\nSi l'équipe est composée uniquement de Corps éveillés de la Chair ou du Chaos, l'effet de « Maîtrise Propagation : Caro » est doublé."
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "Propagation : Caro"
  },
