  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ». \n·La Constitution, l'ATQ et la Défense de ce corps éveillé augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveiller, ce corps éveillé obtient [Arg2] points de Fragment de clé.\n·Les Dégâts Fixes infligés par «Pontos» aux «Affiliés de l'Extase» augmentent de [Arg3]%.\n·«Traque Sans répit» obtient des Dégâts des tentacules égaux à [Arg4]% de l'ATQ pour chaque tranche de 10 Aliemus consommés. Lorsque «Ravage du Décharné» inflige des Dommages, il réduit également temporairement la FOR de la cible d'un montant égal à [Arg5]% de la Défense."
  },
