  AwakerTalent_143615_TalentDesc_1 = {
    Text = "Lorsque ce personnage est dans l'équipe, le Royaume Aequor se transforme en Royaume «Benthos: Aequor».\n\nLes Dommages de base des tentacules sont modifiés à 5% des PV Max de l'équipe.\n\nAmplification de Dégâts de l'équipe +50% après le début de l'exploration (Effet doublé si l'équipe est entièrement composée d'Éveilleurs Aequor et du Chaos, bien qu'aucun tentacule de départ supplémentaire ne soit obtenu).\nL'effet d'Assemblage de tentacules est supprimé.\nLa Posture de tentacule devient «Benthos: Posture de tentacule».\n\n«Benthos: Océan Calme» : Génère immédiatement un Bouclier égal à 25% des PV Max, et les Tentacules n'attaquent plus en fin de tour ; temps de recharge de 3 tours.\n«Benthos: Vagues Déchaînées» : Dégâts des tentacules × 125% pour le tour ; après avoir infligé des Dégâts Directs, 1 Tentacule attaque ; perd 1 Tentacule en fin de tour ; temps de recharge de 3 tours.\nLa Maîtrise de Royaume est comptabilisée comme «Benthos: Maîtrise du fond marin». Chaque point fournit : Génération de Bouclier de la Posture Océan Calme +0,025% des PV Max. Dégâts des tentacules de la Posture Vagues Déchaînées +0,025%.\nL'effet de «Benthos: Maîtrise de Royaume» est doublé si l'équipe est entièrement composée d'Éveilleurs Aequor et du Chaos."
  },
  AwakerTalent_143615_TalentName_1 = {
    Text = "Terre Éternelle des Ombres"
  },
