  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Ce Talent ne prend effet que dans les Niveaux du « Chapitre des Étoiles ».\n·La Constitution, l'Attaque et la Défense de ce Corps éveillé sont augmentées de [Arg1]%, et après que ce Corps éveillé joue l'Éveil pour la première fois, il gagne [Arg2] Fragments de clé.\n·« Épée Trancheuse de Frontières » bénéficie d'un Bonus de Force supplémentaire de [Arg3]%. Après avoir tué un ennemi, gagnez [Arg4] Marques Noires, qui bénéficient du Bonus de Sceaux Obtenus de Lotan : Cétarque. Prend effet au maximum une fois par combat."
  },
