  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Lorsque Caraboo est dans l'équipe, le Royaume de la Chair mute en Propagation : Caro.\n\nFusion d'Embryon : La Fusion d'Embryon gagnée par tour augmente à 50~100, en fonction des PV perdus. Le plafond de Fusion d'Embryon passe de 100 à 200. Lorsque le plafond est atteint, ajoutez 1 « Embryon de Propagule » en main.\n\nEmbryon de Propagule : Jouer cette carte n'accorde plus de Taux Critique. Dévorer n'accorde plus de Bouclier ni de Force Temporaire. La première fois que chaque Corps éveillé consomme un « Embryon de Propagule » par tour, il gagne 40 charges de « Fiesta de propagation » : Chaque charge améliore les effets Finaux suivants de la prochaine Exaltation de ce Corps éveillé ce tour de 1% : Dégâts Finaux, Bouclier Fixe, Régénération de PV Fixe, Force Fixe/Force réduite, Bonus de dégâts des tentacules, Poison Fixe et Contre-attaque Fixe.\n\nForge Écarlate : L'accumulation automatique À chaque début de tour passe à 10% des PV perdus, jusqu'à 50% des PV Max. Ne s'accumule plus à la fin du combat. Temps de recharge de 3 tours.\n\nÉrosion écarlate : Après avoir utilisé la Forge Écarlate, infligez de la Corrosion à tous les ennemis égale à 1% de leurs PV Max. Plus la Forge Écarlate consommée est importante, plus l'effet de Corrosion est puissant, jusqu'à +100%. Inflige un effet de Corrosion 5× contre les ennemis « Coquille vide ».\n\nAu début de l'exploration, PV Max +10%, Amplification de Dégâts de l'équipe +50%, et tous les Corps éveillés gagnent 20 charges de « Fiesta de propagation » À chaque début de tour. Si l'équipe est composée uniquement de Corps éveillés de la Chair ou du Chaos, l'Amplification de Dégâts accordée par cet effet est doublée.\nLa Maîtrise de Royaume devient « Maîtrise Propagation : Caro » : Chaque point de Maîtrise de Royaume augmente les charges de « Fiesta de propagation » gagnées grâce à « Propagation : Caro » de 0,05%.\n\nSi l'équipe est composée uniquement de Corps éveillés de la Chair ou du Chaos, l'effet de « Maîtrise Propagation : Caro » est doublé."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Propagation : Caro"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Lorsque Lotan : Cétarchon est dans l'équipe, le Royaume du Chaos se refond en Primordia : Chaos.\n\nAfflux Primordial : Le Fragment de clé de base est augmenté à 2000, l'Amplification de Dégâts de l'équipe est augmentée de 50%, et l'Attaque et la Défense de tous les Éveilleurs sont augmentées de 10%. Si l'équipe est composée uniquement d'Éveilleurs du royaume du chaos, le bonus d'Amplification de Dégâts de cet effet est doublé. Au début du combat, gagnez 2000 Fragments de clé.\n\nClés Confluentes : Les Niveaux de charge de la clé d'argent de tous les Éveilleurs sont définis sur la moyenne de l'équipe. Les Éveilleurs ne gagnent plus de Fragments de clé grâce à l'Arithmetica consommée ; à la place, la première Carte d'instruction jouée par chaque Éveilleur par tour accorde des Fragments de clé égaux à (leur Régénération de Fragment de clé × 3) + 100.\n\nRoyaume Indivisible : Ne déclenche plus les effets Royaume Pur, Double Maîtrise de Royaume ou Double Amplification de Dégâts des autres Royaumes.\n\nÉcho Primordial : Les Cartes d'Éveil gagnent Prépare 1 ; le Décret Clé actuellement équipé est automatiquement déclenché la première fois qu'il est joué à chaque tour.\n\nFragments de Mémoire : Le Décret Clé est remplacé par Primordia : Double Récurrence et Primordia : Révélation Triade, et le Décret Clé porté lui-même ne peut plus être déclenché.\n\n-Primordia : Double Récurrence : Découvrez 3 Décrets Clés parmi ceux en main, puis choisissez-en 1 à déclencher deux fois.\n-Primordia : Révélation Triade : Découvrez 3 ensembles de Décrets Clés parmi ceux en main, chaque ensemble contenant 3 Décrets Clés différents. Choisissez un ensemble pour déclencher chaque Décret Clé qu'il contient une fois, en séquence.\nLes Décrets Clés présents dans Primordia : Double Récurrence et Primordia : Révélation Triade sont tirés des huit types de Mémoire Primordiale.\nPrimordia : Double Récurrence et Primordia : Révélation Triade comptent chacun comme le déclenchement d'un seul Décret Clé. Lorsque leurs effets se déclenchent plusieurs fois, seul le premier Décret Clé à prendre effet est valide.\n\nMaîtrise du Chaos Primordial : La Maîtrise de Royaume devient Maîtrise du Chaos Primordial. Chaque point de Maîtrise du Chaos Primordial augmente la Puissance du Décret Clé de 0,05%. Chaque point de Puissance du Décret Clé augmente le Poison Fixe, la Contre-attaque Fixe, la Force Fixe, les Cendres anciennes Fixes de 2%, et le Bouclier Fixe, la Régénération de PV Fixe, le gain fixe de Force réduite & Dégâts des tentacules, le Taux Critique, les Dégâts Critiques, l'Amplification de Dégâts, la Maîtrise de Royaume, la Génération de Fureur, la Fusion d'Embryon et la Génération de Fragment de clé de 1%."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Souffle Primordial"
  },
