  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de résistance à la mort fournie par Lily elle-même, sa roue du destin équipée et son pacte, le bouclier de base de « Zone Interdite des Marais Noirs » et de « Défense de base » augmente de 0,25 %, et la quantité et le plafond de patience dans le combat de chef augmentent de 0,25 %.\n·Lorsque Lily est dans l'équipe, pour chaque point de vie perdu, elle gagne 1 couche de patience, le plafond de l'accumulation de patience est égal à la vie maximale."
  },
