  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·L'effet de régénération de la fournaise cramoisie fourni par Salvador bénéficie de l'amélioration de la récupération de vie."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Draenei Cleric"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·Ramona obtient 2.5 points de régénération de la clé en argent supplémentaires. Chaque niveau de taux de synchronisation permet à Ramona d'obtenir 0.5 points de régénération de la clé en argent supplémentaires. \n·Pour chaque point de niveau de régénération de la clé en argent, les dégâts de base de « Épée de la Reine » augmentent de 1 %, et après avoir joué, obtenez 0.75 maîtrise temporaire du domaine."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Résonance du Cœur et de l'Argent"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·Ramona : Vétuste obtient en plus 2,5 points de niveau de charge de la clé d'argent. Chaque niveau de taux de synchronisation permet à Ramona : Vétuste d'obtenir 0,5 point de niveau de charge de la clé d'argent. \n·Pour chaque point de niveau de charge de la clé d'argent, l'effet de boucle de « Attaque de base » permet à Ramona : Vétuste d'obtenir 0,2 % de taux critique, et l'effet de boucle de « Défense de base » permet à Ramona : Vétuste d'obtenir 0,2 Fureur."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Résonance du Cœur et de l'Argent"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·Pour chaque point de maîtrise des royaumes que possède Nautila, la contre-attaque infligée par « Prêt et set » augmente de 0,25 %."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "réparation"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de dégâts puissants que possède Nymphaea, les effets de poison de base causés par « Sonnerie funèbre » et « Mon propre enterrement » augmentent de 0,5 %."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Imprégnation"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "Au début du combat, placez 1 « Obsession » dans votre main.\nLa « Frappe basique » de Miryam bénéficie d'un bonus de 50 % de Dégâts des tentacules.\nPour chaque 1 % de Dégâts Critiques fournis par Miryam et sa Roue du Destin & Concordance équipées, cela augmente la génération de puissance de l'Exaltation, les Dégâts des tentacules, la Fureur, ainsi que l'application et le déclenchement des effets de Poison de 0,2 %."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Dévouement Indestructible"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·Pour chaque point de niveau de recharge de fureur fourni par Tulu lui-même, la Roue du Destin équipée et la Concordance, « Frappe de base » bénéficie d'un bonus de 5 % aux dégâts des tentacules et à la force, tandis que « Ordre des Abysses » bénéficie d'un bonus de 15 % aux dégâts des tentacules et à la force."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Pouvoir du Roi-Dieu"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de résistance à la mort fournie par Sanga elle-même, sa roue du destin équipée et son pacte, la folie obtenue via « Attaque de base » et « Défense de base » augmente de 0,03 points, et « Art Perdu » bénéficie en plus d'un bonus de 0,15 % sur le taux critique et les dégâts critiques."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Inspiration de la mort"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "·Pour chaque point de niveau de recharge de folie possédé par la poupée, l'effet de régénération de vie de « chirurgie extrinsèque » et de « échange équivalent » augmente de 0,5 %."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Désconstruction de la gnose"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'attribut de chute de sigil noir possédé par Ogier, la force temporaire obtenue via « Sept arts et vertus » augmente de 3 %."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Transmutation sans forme"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'attribut de résistance à la mort qu'Alva possède, les dégâts de base augmentent de 0,5 %."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Champ de vision dynamique"
  },
