  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de taux critique possédé par Sorel elle-même, sa roue du destin équipée et son pacte, la folie obtenue via la « Défense de base » augmente de 0,2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Gardien de l'ostentation"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de taux critique fourni par l'éveillé Jenkins lui-même, sa roue du destin et son pacte, les dégâts de base de « Frappe de base » et « Marron, attaque ! » augmentent de 2 %."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Unir nos forces contre l'ennemi"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·Pour chaque point d'attribut de niveau de recharge de clé en argent fourni par l'éveillée Erica elle-même, sa roue du destin et son pacte, «爆破 électromagnétique» lui fait obtenir 0,5 % supplémentaire de taux critique temporaire et de dégâts critiques."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Énergie externe"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·Au début du tour, gagnez 1 niveau d'Appât Onirique. \n · Chaque fois que 1 niveau d'Appât Onirique est consommé, les Contre-attaques de « Gardien égaré » et « Cité des Rêves Morts » dans ce combat augmentent la puissance d'attaque de 5%. \n · Pour chaque 1% d'amplification des dégâts fournie par l'Éveilleur de Wanda, la Roue du Destin et la Concordance, les Contre-attaques de « Cité des Rêves Morts » augmentent de 0.75%."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Révélation"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·Pour chaque point de maîtrise des royaumes fourni par le réveilleur Casiah lui-même, sa roue du destin ou son pacte, « carnaval magique » augmente de 0,2 % tous les dégâts de base de Casiah."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Maître magicien"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'attribut de chute de sigil noir fourni par l'éveillé Tincture lui-même, sa Roue du Destin et son Pacte, « Aurora chromatique » obtient 0,15 % supplémentaire de taux critique temporaire."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Voyageur planétaire"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·Les « Attaques de base » et « Défenses de base » d'Horla sont également considérées comme un poème. Lors du saut quantique du poème, il passera à différentes émotions, qui peuvent directement influencer l'effet de ce poème. Être dans différentes émotions apportera différents effets persistants à l'équipe. \n·Pour chaque 1 % de résistance à la mort qu'Horla possède, cet effet augmente de 0,1 % par rapport à la valeur initiale."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Plume amoureuse"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'efficacité des dégâts supplémentaire possédée par Faros, le bouclier généré par « La cité oubliée depuis longtemps » augmente de 0,4 %."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Obsession du Retour au Pays Natal"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'attribut de chute de sigil noir possédé par Caecus, « Frappe de base » bénéficie d'un bonus de 1 % au comptoir."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Piques rebelles"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·Céleste active une carte de commande pour déclencher 1 tentacule pour attaquer les ennemis ; pour chaque point de maîtrise de royaume venant de Céleste, de la roue et d'un covenant, cette activation inflige 0,5 % de dommages supplémentaires de tentacule."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Corne de navigation"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·Chaque pourcentage d'attribut de chute de sigil noir possédé par Salvador augmente la limite de la fournaise cramoisie de 0,15 % de la vie maximale."
  },
  AwakerTalent_57336_TalentName_1 = {Text = "Au début"},
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "Pour chaque 1 % de Sceaux Obtenus fournis par Agrippa et sa RdD & Concordance équipées, le Bouclier de base de « Abri Pâle » augmente de 0,5 %, et le Poison de base augmente de 1 %."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Marque de pacte"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de résistance à la mort que Faint possède, la contre-attaque fournie par « Berceau des étoiles » et « Éclat Stellaire Sans Limites » augmente de 0,2 %, et les conditions d'effet de la résistance à la mort augmentent de 2 % de résistance à la mort."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Cradle Secondaire"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·Pour chaque 1 % d'amplification des dégâts que possède Hilote, « Survie en milieu hostile » augmente les dégâts qu'il inflige pendant ce tour de 0,3 %."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Cicatrice de douleur"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·Ryker obtient 5 marques noires lorsqu'il élimine un ennemi, chaque 1 % de Sceaux Obtenus par Ryker augmente la quantité obtenue de 1 %, avec un maximum de 5 fois par exploration. \n · Après avoir obtenu 75/150/300 marques noires par le combat, limite de création +1, à la fin du combat, choisissez un <C05_zaowu:«L'héritage du Chaos»> à ajouter à la liste des créations."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Le gagnant prend tout"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·Durant le combat de boss, au début du tour ainsi qu'après que « Doll en fusion » ait libéré son exaltation de la folie, obtenez 1 niveau de « fin ». « Fin » peut accumuler jusqu'à un maximum de 10 niveaux, et en atteignant 10 niveaux, placez 1 carte « Fin du néant » dans votre main."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Chemin de l'Annihilation"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, cet éveilleur obtient [Arg2] points de fragment de clé.\n·Chaque tentacule attaque augmente les dégâts temporaires des tentacules de Tulu de [Arg3] %, actif jusqu'à [Arg4] fois par tour.\n·Lorsqu'il y a 1/2/3 autres éveilleurs « Lémuriens » dans l'équipe, tous les ennemis subissent 10 %/25 %/50 % de dégâts des tentacules en plus."
