  AwakerTalent_74105_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Pour chaque «Division glandulaire» consommée par «Océan bruyant», les Dommages infligés par Aurita dans la suite de ce combat augmentent de [Arg3]% de l'ATQ. En Combat de Chef, si «Océan bruyant» a consommé au moins 20 «Division glandulaire», le nombre de fois que «Division glandulaire» inflige des Dommages lorsqu'elle est jouée ou consommée augmente de +1. Les [Arg4] premières «Division glandulaire» jouées chaque tour n'ajoutent pas d'«Harmonie d'Arithmetica»."
  },
