  AwakerTalent_74106_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, cet éveilleur obtient [Arg2] points de fragment de clé.\n·Les dégâts des tentacules de tous les éveilleurs augmentent de [Arg3] %.\n·Lorsqu'il y a 1/2/3 autre(s) éveilleur(s) « Lémuria » dans l'équipe, les dégâts des tentacules générés par tous les éveilleurs augmentent en plus de 6 %/15 %/30 %."
  },
