    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Le Bouclier infligé par Ogier augmente de [Arg3]%, et la Force infligée augmente de [Arg4]%. Après chaque déclenchement d'Exaltation, le Bouclier infligé par Ogier dans ce combat augmente en plus de 1% de la Défense."
  },
