  AwakerTalent_74109_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, cet éveilleur obtient [Arg2] points de Fragment de clé.\n·Les 10 premières cartes « Brun, attaque ! » jouées chaque tour ne déclencheront pas l'Harmonie d'Arithmetica.\n·Les dégâts infligés par Jenkin augmentent de [Arg3] % de l'Attaque."
