  AwakerTalent_74110_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les étapes du \"Chapitre Stella\".\n·La vitalité, l'attaque et la défense du Réveilleur augmentent de [Arg1] %, et le Réveilleur gagne [Arg2] points de S-énergie après son premier Réveil de Gnose.\n·Après avoir joué \"Inspiration\", obtenez une puissance temporaire égale à [Arg3]% de la puissance d'attaque, et déclenchez 1 fois \"Mélodie du Momentum\", activable jusqu'à 5 fois par tour."
  },
