  AwakerTalent_74111_TalentDesc_1 = {
    Text = "· Ce talent n'est efficace que dans les niveaux \"Règne Astral\".\n· La constitution, l'attaque et la défense de l'éveillé augmentent de [Arg1] %, et cet éveillé gagne [Arg2] points d'énergie argenté à la première illumination.\n· Au début du combat, s'il y a des ennemis \"Bête\", le pouvoir de Casiah dans ce combat augmente de [Arg3] %. \"Pouf\" déclenche l'effet de contre-coup de mélange de la pile de cartes révélées à sa première libération chaque tour."
  },
