  AwakerTalent_74113_TalentDesc_1 = {
    Text = "Ce talent n'est effectif que dans les étapes « Règne Astral ».\nLa Constitution, l'Attaque et la Défense de cet Éveilleur +[Arg1]%, et il obtient [Arg2] Fragment de clé lors de son premier Éveil.\n« Fouet de la Domination Furieuse » gagne Garder et Prépare. Les ennemis avec une intention d'attaque subissent [Arg3]% de Dégâts Directs supplémentaires de la part de Pandia, ce qui augmente de +5% par instance d'attaque supplémentaire, jusqu'à 20%."
