    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, cet éveilleur obtient [Arg2] points de fragment de clé.\n·Les [Arg3] premières cartes « Hurlez, sang ! » jouées chaque tour ne déclencheront pas « Harmonie d'Arithmetica ». Les dommages de base d'Uvhash augmentent de [Arg4] %, et l'effet double si la vie est inférieure à 25 %."
