  AwakerTalent_74117_TalentDesc_1 = {
    Text = "·Ce talent ne prend effet que dans les étapes \"Astral Reign\".\n·Les <awakener>'s <con>, <attack> et <defence> augmentent de [Arg1]%, et lors de la première utilisation du <gnosis> <rouse>, gagnent [Arg2] points de <keyflare>.\n·Après avoir libéré \"Annihilation\", <Winkle> gagne [Arg3] points de <aliemus>, avec un cooldown de 3 tours."
