  AwakerTalent_74118_TalentDesc_1 = {
    Text = "·Ce talent est efficace uniquement dans les étapes \"Règne Astral\".\n·La con, l'atk et la def de cet Éveillé augmentent de [Arg1]%, et lors de l'utilisation initiale de Gnosis Réveil, gagnez de l'énergie Clé Argent de [Arg2].\n·Les dégâts de base de Goliath augmentent de [Arg3]%, et \"Domination de la Lame\" augmente temporairement les dégâts finaux de Goliath de [Arg4]%. \n·Lorsque l'équipe contient 1/2/3 autres Éveillés \"Lémurie\", les effets de gain de force de tous les Éveillés sont en outre renforcés de 6%/15%/30%."
  },
