  AwakerTalent_74119_TalentDesc_1 = {
    Text = "· Ce talent n'est efficace que dans les niveaux \"Règne Astral\".\n· La constitution, l'attaque et la défense de l'éveilleur augmentent de [Arg1] %, et cet éveilleur gagne [Arg2] points d'énergie de clé en argent après la première illumination.\n· Lorsque Tawil joue des cartes appartenant à d'autres éveilleurs de l'équipe, les dégâts finaux, le bouclier et la récupération de PV causés par l'éveilleur correspondant ce tour augmentent de [Arg3] %, et ne peuvent pas se cumuler."
