  AwakerTalent_74120_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Le Dommage de base des Cartes d'instruction de Lotan augmente de [Arg3]%. Chaque fois que Lotan inflige des Dommages, les Dégâts Finaux infligés par Lotan ce tour augmentent de 5%, jusqu'à un maximum de [Arg4]%."
  },
