  AwakerTalent_74122_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Après avoir joué «Son doux s'intensifie», les Dommages infligés par tous les ennemis «Humanoïdes» sont temporairement réduits de [Arg4]%, sans cumul. «Requiem» obtient [Arg3] points d'Aliemus, et en obtient 1 supplémentaire pour chaque État négatif dissipé."
  },
