  AwakerTalent_74123_TalentDesc_1 = {
    Text = "·Ce talent s'active uniquement lors de la phase \"Astral Reign\".\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et lors de la première activation du Réveil de la Gnose, l'éveilleur obtient [Arg2] points d'énergie de Clé d'Argent.\n·Les dégâts de base infligés par \"Frappe\" et \"Coup Précis\" augmentent de [Arg3] % des boucliers obtenus ce round. Les dégâts finaux infligés par Alva aux ennemis du royaume \"Caro\" augmentent de [Arg4] %."
  },
