  AwakerTalent_74124_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, cet éveilleur obtient [Arg2] points de fragment de clé.\n·La folie infligée par Doll et l'effet de soin de l'exaltation augmentent de [Arg3] %, et pour chaque autre éveilleur du royaume « Chaos » dans l'équipe, cet effet est augmenté de [Arg4] %."
  },
