    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ». \n·La vitalité, l'attaque et la défense de ce réveilleur augmentent de [Arg1] %, et après avoir joué pour la première fois une carte d'Éveil, ce réveilleur obtient [Arg2] points de fragment de clé.\n·Celeste génère [Arg3] % de Dégâts des tentacules supplémentaires, et après avoir joué la première Carte d'instruction à chaque tour, déclenche le Talent « Corne de navigation » 4 fois supplémentaires."
