  AwakerTalent_74126_TalentDesc_1 = {
    Text = "· Ce talent n'est efficace qu'aux niveaux \"règne astral\".\n· La con, l'attaque et la défense de cet éveilleur sont augmentées de [Arg1]% et gagne [Arg2] cléflare lors de la première activation de rouse.\n· Les effets de gain de str de Leigh sont augmentés de [Arg4]%, et après avoir joué la \"carte de commandement\" de Leigh, gagne [Arg3]% de l'atk de Leigh en tant que str, cet effet peut augmenter jusqu'à 200% selon les hp perdus actuels, et peut s'activer jusqu'à 3 fois par tour."
