  AwakerTalent_74127_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Pour chaque «Cuisine merveilleuse» en main, les effets de récupération de PV et de Bouclier infligés augmentent de [Arg4]%, jusqu'à 3 cumuls maximum. Pour chaque «Cuisine merveilleuse» jouée, le Poison infligé par Karen dans ce combat augmente de [Arg3]%, jusqu'à 20 cumuls maximum."
  },
  AwakerTalent_74127_TalentDesc_10 = {
