  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Les Dégâts Finaux de l'«Attaque» de Lily augmentent de [Arg3]%, et ce bonus est doublé en Combat de Chef. Après avoir reçu une attaque d'un ennemi «Ultra», obtenir un effet de récupération en Latence de [Arg4]% des PV perdus lors de cette attaque. Les «Frappes de représailles» bénéficient d'un bonus d'Amplification de Dégâts de [Arg5]% en suivant l'effet d'augmentation des Dommages de «Patience»."
  },
