  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Le Poison infligé par Faros augmente de [Arg3]%. À la fin du tour, «La Cité Perdue d'Autrefois» ordonne à tous les Tentacules d'attaquer 1 fois, mais ces attaques n'infligent que [Arg4]% des Dommages.\n·Lorsque l'équipe comprend 1/2/3 autres Corps éveillés «Lémuria», l'Amplification de Dégâts augmente de +20%/50%/100%."
  },
