  AwakerTalent_74135_TalentDesc_1 = {
    Text = "·Ce talent n'est actif que dans les étapes du \"Chapitre Stella\".\n·La vitalité, l'attaque et la défense du Réveilleur augmentent de [Arg1] %, et le Réveilleur gagne [Arg2] points de S-énergie après son premier Réveil de Gnose.\n·Au début du combat de boss, obtenez une résistance à la mort égale à l'attribut de résistance à la mort d'Horla [Arg3]%. Après chaque activation de la résistance à la mort, l'effet du \"Chapitre Fantaisiste\" correspondant augmente de [Arg4]% jusqu'à la fin du tour."
