  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·Ce Talent n'est actif que dans les niveaux du «Chapitre des Étoiles».\n·La Constitution, l'ATQ et la Défense de ce Corps éveillé augmentent de [Arg1] %, et après avoir joué Éveiller pour la première fois, ce Corps éveillé obtient [Arg2] points de Fragment de clé.\n·Lors du Rafraîchissement des «Ruines Cendrées», la probabilité d'apparition d'une remise augmente de [Arg3]%, et le taux de remise augmente de [Arg4]%.\n·Le Dommage de base du «Coup de cou» augmente de [Arg5] %, calculé indépendamment de l'augmentation du Dommage de base apportée par l'Élimination."
  },
