  AwakerTalent_74138_TalentDesc_1 = {
    Text = "·Ce talent n'est efficace que lors de la phase \"règne astral\".\n·La constitution, l'attaque et la défense des éveilleurs augmentent de [Arg1] %, et lors de la première utilisation d'éveil, l'éveiller gagne [Arg2] points d'énergie de clé argentée.\n·Caecus joue la première carte de commande à chaque tour pour restaurer [Arg3] % des hp de sa constitution. Les attaques de tentacule et les effets de contre à partir de la \"lignée d'hérésie\" infligent également [Arg4] % de dégâts."
  },
