  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Ce talent s'active uniquement lors de la phase \"Astral Reign\".\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et lors de la première activation du Réveil de la Gnose, l'éveilleur obtient [Arg2] points d'énergie de Clé d'Argent.\n·L'effet de dégâts de base appliqué par \"Rédemption de l'Agonie\" augmente la puissance d'attaque de Pollux de [Arg3] %.\n·Chaque pile de 50 couches de \"Marque de Péché\" place un \"Cœur Sacré\" dans la main.\n·Lorsque \"Marque de Péché\" atteint 100 couches, piochez une de vos propres \"Carte de Compétence\" après la troisième consommation.\n·Lorsqu'il inflige des dégâts, les effets de \"Marque de Péché\" sur les ennemis de l'\"Église des Porteurs de Lumière\" doublent."
  },
  AwakerTalent_78618_TalentDesc_10 = {
    Text = "·Ce talent s'active uniquement lors de la phase \"Astral Reign\".\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et lors de la première activation du Réveil de la Gnose, l'éveilleur obtient [Arg2] points d'énergie de Clé d'Argent.\n·L'effet de dégâts de base appliqué par \"Rédemption de l'Agonie\" augmente la puissance d'attaque de Pollux de [Arg3] %.\n·Chaque pile de 50 couches de \"Marque de Péché\" place un \"Cœur Sacré\" dans la main.\n·Lorsque \"Marque de Péché\" atteint 100 couches, piochez une de vos propres \"Carte de Compétence\" après la troisième consommation.\n·Lorsqu'il inflige des dégâts, les effets de \"Marque de Péché\" sur les ennemis de l'\"Église des Porteurs de Lumière\" doublent."
  },
