  AwakerTalent_78620_TalentDesc_1 = {
    Text = "Ce talent n'est effectif que dans les étapes « Règne Astral ».\nLa Constitution, l'Attaque et la Défense de cet Éveilleur +[Arg1]%, et il obtient [Arg2] Fragment de clé lors de son premier Éveil.\nAu début du combat, tous les ennemis subissent [Arg3]% de Dégâts des tentacules supplémentaires. Cet effet est doublé contre les ennemis « Aequor ». Les Dégâts Directs infligés par « Châtiment du Tonnerre » aux ennemis « Aequor » +[Arg4]%."
  },
