  AwakerTalent_78622_TalentDesc_1 = {
    Text = "·Ce talent n'entre en vigueur que dans les étapes du \"Chapitre Stella\".\n·La vitalité, l'attaque et la défense du Réveilleur augmentent de [Arg1] %, et le Réveilleur gagne [Arg2] points de S-énergie après son premier Réveil de Gnose.\n·L'effet d'amélioration de \"Flamme Vivante\" augmente de [Arg3] %, au début du tour et avant la phase de défausse, effacez toutes les \"Brûlures\" de la main ; pour chaque couche, Kaitigra gagne 1 couche de \"Flamme Explosive\"."
  },
