  AwakerTalent_78624_TalentDesc_1 = {
    Text = "· Ce talent n'est efficace que dans les niveaux \"Règne Astral\".\n· La constitution, l'attaque et la défense de l'éveillé augmentent de [Arg1] %, et cet éveillé gagne [Arg2] points d'énergie argenté à la première illumination.\n· Jouer \"Plume d'Onyx\" n'ajoute pas \"Harmonie Arithmetica\", et la corrosion infligée par \"Plumes Purificatrices\" augmente la puissance d'attaque de Castor de [Arg3] %.\n· La corrosion infligée par Castor sur les ennemis de \"L'Église des Porte-Lumières\" augmente de [Arg4] %."
