  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Ce talent s'active uniquement lors de la phase \"Astral Reign\".\n·La constitution, l'attaque et la défense de cet éveilleur augmentent de [Arg1] %, et lors de la première activation du Réveil de la Gnose, l'éveilleur obtient [Arg2] points d'énergie de Clé d'Argent.\n·La force acquise par tous les éveilleurs augmente de [Arg3] %.\n·Clementine applique un effet de saignement infligeant [Arg4] % de dégâts aux cibles lorsqu'elle attaque les ennemis \"insectoïdes\". Lorsque Clementine génère un bouclier ou récupère des points de vie pour la première fois chaque round, les ennemis \"insectoïdes\" perdent temporairement [Arg5] % de leur défense."
  },
