    Text = "·Ce talent n'est actif que dans les niveaux du « Chapitre des Étoiles ».\n·La Constitution, l'Attaque et la Défense de ce Corps éveillé augmentent de [Arg1] %, et il obtient [Arg2] Fragment de clé après son premier Éveil.\n·Chaque fois que Murphy : Égarée inflige des Dommages, elle inflige à la cible des charges de « Sacrifice » égales à [Arg3]% des Dommages infligés. L'effet d'augmentation des charges de « Rituel de descente » de l'état « Contrat du Destin » est doublé.\n·Lorsqu'il y a 1/2/3 autre(s) Corps éveillé(s) « Lémurien(s) » dans l'équipe : PV Max +6%/15%/30% ; obtient un Bouclier du personnage égal à 50%/125%/250% de la Défense de Murphy : Égarée après qu'un Corps éveillé « Lémurien » utilise une Exaltation. Limité à une fois par tour ; ne bénéficie pas du bonus de génération de Bouclier."
