  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·Les cartes d'instruction de Clémentine infligent des dégâts et obtiennent 1 couche d'« empathie ».\n·Pour chaque point de régénération de fragment de clé fourni par Clémentine, l'Éveilleur, la Roue du Destin et la Concordance, le taux critique et les dégâts critiques augmentent de 0,35 %.\n·Après le début du Tour Ultra, retirez toutes les couches de « trauma mental » et de « fixation phobique » de tous les ennemis. Pour chaque couche de « trauma mental » retirée de tous les ennemis, obtenez 50 points de fragment de clé, et pour chaque couche de « fixation phobique » retirée de tous les ennemis, faites obtenir 2 points de fureur aux autres Éveilleurs."
  },
  AwakerTalent_79211_TalentName_1 = {
    Text = "Sens de la ruche"
  },
  AwakerTalent_79788_TalentDesc_1 = {
