  AwakerTalent_83778_TalentDesc_1 = {
    Text = "·Pour chaque 1 % de résistance à la mort fourni par Kepsente elle-même, sa roue du destin équipée et son pacte, les dégâts de base augmentent de 0,2 % et le bouclier augmente de 0,05 %."
  },
  AwakerTalent_83778_TalentName_1 = {Text = "Braise"},
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "Pour chaque 1 Niveau de recharge de fureur d'Aurita, au début du combat, obtenez 1 % de l'Attaque d'Aurita en Dégâts des tentacules."
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "Heureux lutin"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "Chaque fois que vous jouez « Plume Noire » pour la première fois dans un tour, appliquez « Corrosion » équivalente à 840 % de l'Attaque de Castor à la cible et obtenez 10 points de Fureur.\nPour chaque 1 % d'Amplification de Dégâts de Castor, la Corrosion de base appliquée augmente de 1 %.\nÀ la fin du combat, la Corrosion appliquée par Castor durant cette exploration augmente de 20 % de manière permanente.\nLa Corrosion appliquée lors du Combat de Chef est doublée.\nAprès avoir appliqué la Corrosion, les dégâts infligés par Castor augmentent de 5 % du montant de Corrosion appliqué durant ce tour.\nLes dégâts infligés par Castor ne retirent pas la Corrosion."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "Plumes saintes de purification"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "·Doresain collecte 1 « Cadavre » après avoir tué un ennemi ou infligé des DMG d'Exalt à un Boss.\n·Il peut conserver jusqu'à 3 empilements de « Cadavre ».\n·Le « Cadavre » est conservé tout au long de l'exploration."
  },
